def _find_free_port(start=8888, max_tries=10):
    """Find a free port starting from `start`."""
    import socket
    for port in range(start, start + max_tries):
        try:
            s = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
            s.bind(('127.0.0.1', port))
            s.close()
            return port
        except OSError:
            continue
    return None

def _kill_process_on_port(port):
    """Kill any process listening on the given port.
    Uses netstat + taskkill instead of psutil to avoid attribute name issues
    across different psutil versions (e.g. 'connections' vs 'connections')."""
    try:
        import subprocess
        out = subprocess.run(
            ['netstat', '-ano', '-p', 'tcp'],
            capture_output=True, text=True, timeout=5
        )
        for line in out.stdout.split('\n'):
            if f':{port} ' in line and 'LISTENING' in line:
                parts = line.strip().split()
                if len(parts) >= 5:
                    pid = parts[-1]
                    if pid.isdigit():
                        subprocess.run(['taskkill', '/pid', pid, '/f'],
                                       capture_output=True, timeout=3)
                        time.sleep(0.5)
                        return True
    except Exception:
        pass
    return False

def _auto_start_llm():
    """Auto-start Unsloth or LM Studio if not already running."""
    global _LLM_STARTED, _LLM_PROCESS
    if _LLM_STARTED:
        return

    # Check if Unsloth is already running
    try:
        r = httpx.get("http://127.0.0.1:8888/v1/models", timeout=2.0)
        if r.status_code == 200:
            _LLM_STARTED = True
            print("[Soul Core] Unsloth already running on :8888")
            return
    except Exception:
        pass

    # Check if LM Studio is already running
    try:
        r = httpx.get("http://127.0.0.1:7272/v1/models", timeout=2.0)
        if r.status_code == 200:
            _LLM_STARTED = True
            print("[Soul Core] LM Studio already running on :7272")
            return
    except Exception:
        pass

    # Determine which LLM to start
    provider = os.environ.get("LUMAX_CHAT_PROVIDER", "unsloth").lower()
    engine = os.environ.get("LUMAX_LOCAL_ENGINE", "unsloth").lower()
    model_path = os.environ.get("LUMAX_MODEL_LOCAL_PATH", "")

    if not model_path:
        print("[Soul Core] No LUMAX_MODEL_LOCAL_PATH set, skipping auto-start LLM")
        return

    if provider == "unsloth" or engine == "unsloth":
        # Kill any existing process on :8888
        _kill_process_on_port(8888)

        # Find a free port
        port = _find_free_port(8888)
        if port is None:
            print("[Soul Core] No free port found for Unsloth")
            return

        # Start Unsloth server
        try:
            cmd = [
                "python", "-m", "unsloth.chat",
                "--model", model_path,
                "--port", str(port),
                "--host", "127.0.0.1"
            ]
            _LLM_PROCESS = subprocess.Popen(
                cmd,
                stdout=subprocess.DEVNULL,
                stderr=subprocess.DEVNULL,
                creationflags=subprocess.CREATE_NO_WINDOW if hasattr(subprocess, 'CREATE_NO_WINDOW') else 0
            )
            _LLM_STARTED = True
            print(f"[Soul Core] Started Unsloth on :{port}")
        except Exception as e:
            print(f"[Soul Core] Failed to start Unsloth: {e}")

    elif provider == "lmstudio" or engine == "lmstudio":
        # Kill any existing process on :7272
        _kill_process_on_port(7272)

        # Start LM Studio
        try:
            lmstudio_path = "C:\\Program Files\\LM Studio\\lmstudio.exe"
            if os.path.exists(lmstudio_path):
                cmd = [
                    lmstudio_path, "run", model_path,
                    "--port", "7272",
                    "--host", "127.0.0.1"
                ]
                _LLM_PROCESS = subprocess.Popen(
                    cmd,
                    stdout=subprocess.DEVNULL,
                    stderr=subprocess.DEVNULL,
                    creationflags=subprocess.CREATE_NO_WINDOW if hasattr(subprocess, 'CREATE_NO_WINDOW') else 0
                )
                _LLM_STARTED = True
                print("[Soul Core] Started LM Studio on :7272")
            else:
                print(f"[Soul Core] LM Studio not found at {lmstudio_path}")
        except Exception as e:
            print(f"[Soul Core] Failed to start LM Studio: {e}")

    else:
        print(f"[Soul Core] Unknown provider: {provider}, skipping auto-start")

