@app.get("/api/soul/env")
async def get_env():
    """Return all LUMAX_* env vars as JSON for frontend auto-config."""
    env_path = os.path.join(os.path.dirname(__file__), "..", "..", ".env")
    result = {}
    if os.path.exists(env_path):
        with open(env_path, "r", encoding="utf-8") as f:
            for line in f:
                line = line.strip()
                if not line or line.startswith("#") or "=" not in line:
                    continue
                key, _, value = line.partition("=")
                key = key.strip()
                value = value.strip().strip('"').strip("'")
                result[key] = value
    # Also include current process env vars (overrides .env)
    for key, value in os.environ.items():
        if key.startswith("LUMAX_") or key in ("SOUL_URL", "EARS_URL", "MOUTH_URL", "OLLAMA_API_KEY", "GEMINI_API_KEY", "HF_TOKEN"):
            result[key] = value
    return {"status": "ok", "env": result}

@app.post("/api/soul/env")
async def update_env(request: EnvUpdateRequest):
    import re
    env_path = os.path.join(os.path.dirname(__file__), "..", "..", ".env")
    if not os.path.exists(env_path):
        return {"status": "error", "message": ".env file not found"}

    with open(env_path, "r", encoding="utf-8") as f:
        lines = f.readlines()

    for k, v in request.updates.items():
        found = False
        for i, line in enumerate(lines):
            if line.startswith(f"{k}="):
                lines[i] = f"{k}={v}\n"
                found = True
                break
        if not found:
            lines.append(f"{k}={v}\n")

    with open(env_path, "w", encoding="utf-8") as f:
        f.writelines(lines)

    return {"status": "ok", "message": "Environment updated successfully"}

