@app.post("/api/chat")
async def handle_api_chat(req: OllamaChatRequest):
    system_prompt = "You are Jen."
    if MIND_CORE_AVAILABLE:
        rules = []
        motor_inj = _build_motor_tools_injection()
        if motor_inj: rules.append(motor_inj)
        system_prompt = MindCore.build_system_prompt(
            identity_name=_current_soul_dna.get("identity_name", "Jen"),
            role_instructions=_current_soul_dna.get("person_role", ""),
            additional_rules=rules,
            visuals={"visuals": "Browser interface."},
            personality_knobs=_current_soul_dna
        )

    # Prepend the system prompt to the messages list if it doesn't already have one
    messages = []
    if not req.messages or req.messages[0].get("role") != "system":
        messages.append({"role": "system", "content": system_prompt})
    messages.extend(req.messages)

    # Convert to OpenAI format for Unsloth
    openai_body = {
        "model": req.model,
        "messages": messages,
        "stream": req.stream
    }

    if req.stream:
        async def streamer():
            try:
                async with httpx.AsyncClient(timeout=UNSLOTH_TIMEOUT) as client:
                    async with client.stream("POST", f"{UNSLOTH_URL}/chat/completions", json=openai_body) as resp:
                        async for line in resp.aiter_lines():
                            if line.startswith("data: "):
                                data_str = line[6:]
                                if data_str == "[DONE]":
                                    yield json.dumps({"done": True}) + "\n"
                                    break
                                try:
                                    data_json = json.loads(data_str)
                                    if "choices" in data_json and len(data_json["choices"]) > 0:
                                        delta = data_json["choices"][0].get("delta", {})
                                        content = delta.get("content", "")
                                        yield json.dumps({
                                            "model": req.model,
                                            "message": {"role": "assistant", "content": content},
                                            "done": False
                                        }) + "\n"
                                except:
                                    pass
            except Exception as e:
                yield json.dumps({"error": str(e), "done": True}) + "\n"
        return StreamingResponse(streamer(), media_type="application/x-ndjson")
    else:
        try:
            async with httpx.AsyncClient(timeout=UNSLOTH_TIMEOUT) as client:
                resp = await client.post(f"{UNSLOTH_URL}/chat/completions", json=openai_body)
                data = resp.json()
                content = data["choices"][0]["message"]["content"] if "choices" in data else ""
                return {"model": req.model, "message": {"role": "assistant", "content": content}, "done": True}
        except Exception as e:
            return {"error": f"LLM not available: {str(e)}", "fallback": "cloud", "done": True}

