    structured_output = payload.get("structured_output")

    if provider:
        os.environ["LUMAX_CHAT_PROVIDER"] = provider
        # Persist to .env
        try:
            env_path = os.path.join(os.path.dirname(__file__), "..", "..", ".env")
            if os.path.exists(env_path):
                with open(env_path, "r", encoding="utf-8") as f:
                    lines = f.readlines()
                found = False
                for i, line in enumerate(lines):
                    if line.startswith("LUMAX_CHAT_PROVIDER="):
                        lines[i] = f"LUMAX_CHAT_PROVIDER={provider}\n"
                        found = True
                        break
                if not found:
                    lines.append(f"LUMAX_CHAT_PROVIDER={provider}\n")
                with open(env_path, "w", encoding="utf-8") as f:
                    f.writelines(lines)
        except Exception:
            pass

    if local_vision is not None:
        os.environ["LUMAX_LOCAL_VISION"] = str(local_vision).lower()

    if structured_output is not None:
        os.environ["LUMAX_STRUCTURED_OUTPUT"] = str(structured_output).lower()

