    # Simple thresholding before invoking the LLM to save tokens
    if sensor_type == "accelerometer":
        # Check for violent shaking
        x, y, z = body.get("x", 0), body.get("y", 0), body.get("z", 0)
        magnitude = (x**2 + y**2 + z**2)**0.5
