    r = _get_redis()
    if r:
        try:
            key = f"lumax:{IDENTITY}:session:{session_id}"
            items = r.lrange(key, 0, limit - 1)
            return [json.loads(x) for x in items]
        except Exception as e:
            print(f"Redis history error: {e}")
    return []

