            const saved = fmtNum(s.saved).padStart(10);
            const pct = (s.reductionPercent + '%').padStart(5);
            lines.push(`  ${langName} ${dim('files=')}${files}  ${dim('saved=')}${green(saved)}  ${yellow(pct)}`);
