        'analyses',
        'calls',
        'unique_files',
        'original_tokens',
        'compacted_tokens',
        'tokens_saved',
        'reduction_percent',
        'est_cost_gpt4o_usd',
        'est_cost_claude_usd',
        'mom_saved_delta',
        'mom_saved_percent',
        'mom_analyses_delta',
    ].join(',');
    if (agg.byMonth.length === 0) {
        return header + '\n';
    }
    const rows = agg.byMonth.map(m => [
        m.month,
        m.analyses,
        m.calls,
        m.uniqueFiles,
        m.original,
        m.compacted,
        m.saved,
        m.reductionPercent,
        m.estimatedCost.gpt4o.toFixed(2),
        m.estimatedCost.claudeSonnet.toFixed(2),
        m.momSavedDelta ?? '',
        m.momSavedPercent ?? '',
        m.momAnalysesDelta ?? '',
    ].join(','));
    return [header, ...rows].join('\n') + '\n';
}

