      margin-bottom: 24px;
    }
    .header-left { }
    h1 {
      font-size: 24px;
      margin: 0 0 4px;
      background: linear-gradient(90deg, var(--accent), var(--accent-2));
      -webkit-background-clip: text;
      background-clip: text;
      color: transparent;
      display: inline-block;
    }
