#!/usr/bin/env node
/**
 * TokenSlayer Batch Statistics — processes multiple files and prints aggregate savings.
 * Usage: node tokenslayer-batch.js file1.py file2.ts ...
 *        node tokenslayer-batch.js src/**\*.py
 */

const { execSync } = require('child_process');
const path = require('path');
const fs = require('fs');

const args = process.argv.slice(2);
if (args.length === 0) {
  console.log('Usage: node tokenslayer-batch.js <file1> <file2> ...');
  process.exit(1);
}

const tsPath = path.join(__dirname, 'tokenslayer.js');
let totalOrig = 0;
let totalSaved = 0;
let fileCount = 0;
const results = [];

console.log('============================================');
console.log('  TokenSlayer Batch Statistics');
console.log('============================================');
console.log('');

for (const filePattern of args) {
  // Expand globs manually (simple wildcard support)
  const dir = path.dirname(filePattern);
  const base = path.basename(filePattern);

  let files = [];
  if (base.includes('*')) {
    const regex = new RegExp('^' + base.replace(/\*/g, '.*').replace(/\./g, '\\.') + '$');
    try {
      const entries = fs.readdirSync(dir || '.');
      files = entries.filter(e => regex.test(e)).map(e => path.join(dir, e));
    } catch {
      files = [filePattern]; // fallback: pass as-is
    }
  } else {
    files = [filePattern];
  }

  for (const file of files) {
    if (!fs.existsSync(file)) continue;

    try {
      const output = execSync(`node "${tsPath}" "${file}"`, {
        encoding: 'utf8',
        stdio: ['pipe', 'pipe', 'pipe'],
        timeout: 10000,
      });

      // Parse: [TokenSlayer Saved 83% (2448 -> 413 tokens)]
      const match = output.match(/TokenSlayer Saved \d+% \((\d+) -> (\d+) tokens\)/);
      if (match) {
        const orig = parseInt(match[1], 10);
        const saved = parseInt(match[2], 10);
        totalOrig += orig;
        totalSaved += saved;
        fileCount++;
        results.push({ file, orig, saved });
        console.log(`[${file}] ${orig.toLocaleString()} -> ${saved.toLocaleString()} tokens`);
      }
    } catch (err) {
      // Skip files that TokenSlayer can't process
    }
  }
}

if (fileCount === 0) {
  console.log('No processable files found.');
  process.exit(1);
}

const savedTokens = totalOrig - totalSaved;
const savedPct = totalOrig > 0 ? Math.round((savedTokens / totalOrig) * 100) : 0;

console.log('');
console.log('--------------------------------------------');
console.log(`Files processed: ${fileCount}`);
console.log(`Total original tokens: ${totalOrig.toLocaleString()}`);
console.log(`Total skeleton tokens: ${totalSaved.toLocaleString()}`);
console.log(`Tokens saved: ${savedTokens.toLocaleString()} (${savedPct}%)`);
console.log('--------------------------------------------');
console.log('');
console.log('Cost estimate (DeepSeek V4 @ $0.14/1M input tokens):');
console.log(`  Without TokenSlayer: $${((totalOrig / 1_000_000) * 0.14).toFixed(4)}`);
console.log(`  With TokenSlayer:    $${((totalSaved / 1_000_000) * 0.14).toFixed(4)}`);
console.log(`  Savings:             $${((savedTokens / 1_000_000) * 0.14).toFixed(4)}`);
console.log('');

