#!/usr/bin/env node
/**
 * TokenSlayer Live Dashboard — zero-dependency HTTP server + stats tracker.
 *
 * Start:   node tokenslayer-dashboard.js
 * Open:    http://localhost:8104
 *
 * API:
 *   GET  /api/stats        — current aggregate statistics (JSON)
 *   POST /api/log          — log a TokenSlayer invocation
 *   GET  /api/history      — last 100 invocations
 *   GET  /                 — live HTML dashboard
 */

const http = require('http');
const fs = require('fs');
const path = require('path');

const PORT = 8104;
const LOG_FILE = path.join(__dirname, '.tokenslayer-stats.jsonl');
const STATS_FILE = path.join(__dirname, '.tokenslayer-aggregate.json');

// ---- In-memory state ----
let aggregate = { totalFiles: 0, totalOrig: 0, totalSaved: 0, byLang: {}, history: [] };
const MAX_HISTORY = 200;

// Load persisted state
function loadState() {
  try {
    if (fs.existsSync(STATS_FILE)) {
      aggregate = JSON.parse(fs.readFileSync(STATS_FILE, 'utf8'));
      if (!aggregate.byLang) aggregate.byLang = {};
      if (!aggregate.history) aggregate.history = [];
    }
  } catch {}
}
loadState();

function saveState() {
  fs.writeFileSync(STATS_FILE, JSON.stringify(aggregate, null, 2));
}

function logInvocation(entry) {
  aggregate.totalFiles++;
  aggregate.totalOrig += entry.orig;
  aggregate.totalSaved += entry.saved;
  const lang = entry.lang || 'unknown';
  if (!aggregate.byLang[lang]) aggregate.byLang[lang] = { files: 0, orig: 0, saved: 0 };
  aggregate.byLang[lang].files++;
  aggregate.byLang[lang].orig += entry.orig;
  aggregate.byLang[lang].saved += entry.saved;
  aggregate.history.unshift({ ...entry, time: new Date().toISOString() });
  if (aggregate.history.length > MAX_HISTORY) aggregate.history.length = MAX_HISTORY;
  saveState();
  // Also append to JSONL for external consumers
  fs.appendFileSync(LOG_FILE, JSON.stringify({ ...entry, time: new Date().toISOString() }) + '\n');
}

// ---- HTML Dashboard ----
function getDashboardHTML() {
  const saved = aggregate.totalOrig - aggregate.totalSaved;
  const pct = aggregate.totalOrig > 0 ? Math.round((saved / aggregate.totalOrig) * 100) : 0;
  const costPerM = 0.14; // DeepSeek V4
  const costSaved = ((saved / 1_000_000) * costPerM).toFixed(4);

  let langRows = '';
  for (const [lang, stats] of Object.entries(aggregate.byLang).sort((a, b) => b[1].files - a[1].files)) {
    const ls = stats.orig - stats.saved;
    const lp = stats.orig > 0 ? Math.round((ls / stats.orig) * 100) : 0;
    langRows += `<tr><td>${lang}</td><td>${stats.files}</td><td>${stats.orig.toLocaleString()}</td><td>${stats.saved.toLocaleString()}</td><td>${lp}%</td></tr>`;
  }

  let historyRows = '';
  for (const h of aggregate.history.slice(0, 20)) {
    const hp = h.orig > 0 ? Math.round(((h.orig - h.saved) / h.orig) * 100) : 0;
    historyRows += `<tr><td style="font-size:11px">${h.time?.slice(11,19) || '--'}</td><td>${h.file || '—'}</td><td>${h.lang || '—'}</td><td>${(h.orig || 0).toLocaleString()}</td><td>${(h.saved || 0).toLocaleString()}</td><td style="color:#4caf50">${hp}%</td></tr>`;
  }

  return `<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>TokenSlayer Dashboard</title>
<style>
  * { margin: 0; padding: 0; box-sizing: border-box; }
  body { font-family: 'Segoe UI', system-ui, sans-serif; background: #0d1117; color: #c9d1d9; padding: 24px; }
  h1 { color: #58a6ff; margin-bottom: 4px; }
  .subtitle { color: #8b949e; margin-bottom: 24px; font-size: 14px; }
  .cards { display: grid; grid-template-columns: repeat(auto-fit, minmax(200px, 1fr)); gap: 16px; margin-bottom: 24px; }
  .card { background: #161b22; border: 1px solid #30363d; border-radius: 8px; padding: 16px; }
  .card .label { font-size: 12px; color: #8b949e; text-transform: uppercase; letter-spacing: 0.5px; }
  .card .value { font-size: 28px; font-weight: 700; color: #58a6ff; margin-top: 4px; }
  .card .value.green { color: #3fb950; }
  .card .value.orange { color: #d2991d; }
  table { width: 100%; border-collapse: collapse; margin-bottom: 24px; }
  th, td { text-align: left; padding: 8px 12px; border-bottom: 1px solid #21262d; font-size: 13px; }
  th { color: #8b949e; font-weight: 600; text-transform: uppercase; font-size: 11px; letter-spacing: 0.5px; }
  tr:hover { background: #1c2128; }
  .section-title { color: #f0f6fc; font-size: 16px; font-weight: 600; margin: 24px 0 12px; padding-bottom: 8px; border-bottom: 1px solid #30363d; }
  .empty { color: #484f58; padding: 24px; text-align: center; }
  .refresh { font-size: 12px; color: #8b949e; }
  .api-box { background: #161b22; border: 1px solid #30363d; border-radius: 8px; padding: 16px; margin-top: 24px; }
  .api-box h3 { color: #f0f6fc; margin-bottom: 8px; font-size: 14px; }
  .api-box code { background: #0d1117; padding: 2px 6px; border-radius: 4px; font-size: 12px; color: #7ee787; }
  .api-box pre { background: #0d1117; padding: 12px; border-radius: 6px; overflow-x: auto; font-size: 12px; color: #c9d1d9; margin-top: 8px; }
</style>
</head>
<body>
  <h1>🪓 TokenSlayer Dashboard</h1>
  <p class="subtitle">Live token savings tracker — <span class="refresh">auto-refreshes every 5s</span></p>

  <div class="cards">
    <div class="card">
      <div class="label">Files Processed</div>
      <div class="value">${aggregate.totalFiles.toLocaleString()}</div>
    </div>
    <div class="card">
      <div class="label">Tokens Saved</div>
      <div class="value green">${saved.toLocaleString()}</div>
    </div>
    <div class="card">
      <div class="label">Savings Rate</div>
      <div class="value green">${pct}%</div>
    </div>
    <div class="card">
      <div class="label">Est. Cost Saved</div>
      <div class="value orange">$${costSaved}</div>
    </div>
  </div>

  <div class="section-title">📊 By Language</div>
  ${aggregate.totalFiles > 0 ? `<table><thead><tr><th>Language</th><th>Files</th><th>Orig Tokens</th><th>Skeleton Tokens</th><th>Savings</th></tr></thead><tbody>${langRows}</tbody></table>` : '<p class="empty">No data yet. Run TokenSlayer on some files!</p>'}

  <div class="section-title">🕐 Recent Activity</div>
  ${aggregate.history.length > 0 ? `<table><thead><tr><th>Time</th><th>File</th><th>Lang</th><th>Orig</th><th>Saved</th><th>Savings</th></tr></thead><tbody>${historyRows}</tbody></table>` : '<p class="empty">No invocations logged yet.</p>'}

  <div class="api-box">
    <h3>🔌 API Endpoints</h3>
    <p style="font-size:13px;color:#8b949e;margin-bottom:8px">Other tools can POST usage data to keep the dashboard updated:</p>
    <pre># Log a TokenSlayer invocation
curl -X POST http://localhost:8104/api/log \\
  -H "Content-Type: application/json" \\
  -d '{"file":"src/main.py","lang":"python","orig":2448,"saved":413}'

# Get current stats
curl http://localhost:8104/api/stats

# Get invocation history
curl http://localhost:8104/api/history</pre>
  </div>

  <script>
    setTimeout(() => location.reload(), 5000);
  </script>
</body>
</html>`;
}

// ---- HTTP Server ----
const server = http.createServer((req, res) => {
  res.setHeader('Access-Control-Allow-Origin', '*');
  res.setHeader('Access-Control-Allow-Methods', 'GET, POST, OPTIONS');
  res.setHeader('Access-Control-Allow-Headers', 'Content-Type');

  if (req.method === 'OPTIONS') {
    res.writeHead(204);
    return res.end();
  }

  const url = new URL(req.url, `http://localhost:${PORT}`);

  // GET / — Dashboard
  if (req.method === 'GET' && url.pathname === '/') {
    res.writeHead(200, { 'Content-Type': 'text/html; charset=utf-8' });
    return res.end(getDashboardHTML());
  }

  // GET /api/stats
  if (req.method === 'GET' && url.pathname === '/api/stats') {
    res.writeHead(200, { 'Content-Type': 'application/json' });
    return res.end(JSON.stringify(aggregate));
  }

  // GET /api/history
  if (req.method === 'GET' && url.pathname === '/api/history') {
    res.writeHead(200, { 'Content-Type': 'application/json' });
    return res.end(JSON.stringify(aggregate.history));
  }

  // POST /api/log
  if (req.method === 'POST' && url.pathname === '/api/log') {
    let body = '';
    req.on('data', chunk => body += chunk);
    req.on('end', () => {
      try {
        const entry = JSON.parse(body);
        if (!entry.file || !entry.orig || !entry.saved) {
          res.writeHead(400, { 'Content-Type': 'application/json' });
          return res.end(JSON.stringify({ error: 'Missing required fields: file, orig, saved' }));
        }
        logInvocation(entry);
        res.writeHead(200, { 'Content-Type': 'application/json' });
        return res.end(JSON.stringify({ ok: true, aggregate }));
      } catch (e) {
        res.writeHead(400, { 'Content-Type': 'application/json' });
        return res.end(JSON.stringify({ error: 'Invalid JSON' }));
      }
    });
    return;
  }

  // POST /api/reset
  if (req.method === 'POST' && url.pathname === '/api/reset') {
    aggregate = { totalFiles: 0, totalOrig: 0, totalSaved: 0, byLang: {}, history: [] };
    saveState();
    res.writeHead(200, { 'Content-Type': 'application/json' });
    return res.end(JSON.stringify({ ok: true, message: 'Stats reset' }));
  }

  res.writeHead(404, { 'Content-Type': 'application/json' });
  res.end(JSON.stringify({ error: 'Not found' }));
});

server.listen(PORT, () => {
