#!/usr/bin/env node
/**
 * TokenSlayer Standalone Parser — Developer's X-Ray
 * Zero-dependency codebase structural extractor for any IDE/Agent.
 *
 * Usage: node tokenslayer.js <filepath> [options]
 *
 * Options:
 *   --level <0-5>    Skeletonization level (default: 2)
 *                     0 = full file (no reduction)
 *                     1 = light (keep comments, docstrings, signatures + bodies)
 *                     2 = medium (keep imports, decorators, signatures, top-level vars)
 *                     3 = deep (keep only imports and signatures)
 *                     4 = ultra (symbol table: file:line name(params) — no types, no defaults)
 *                     5 = atomic (hash-based: file:line #hash — expand on demand)
 *   --html           Force HTML parsing mode
 *   --md             Force Markdown parsing mode
 *   --hash           Output hash-based atomic mode (same as --level 5)
 *   --tier <micro|standard|full>  Output tiered skeleton (overrides --level)
 *
 * Examples:
 *   node tokenslayer.js main.js
 *   node tokenslayer.js index.html --level 1
 *   node tokenslayer.js soul_core.py --level 4
 *   node tokenslayer.js soul_core.py --level 5
 *   node tokenslayer.js soul_core.py --tier micro
 */

const fs = require('fs');
const path = require('path');
const crypto = require('crypto');

// Parse CLI args
const args = process.argv.slice(2);
let filePath = null;
let skeletonLevel = 2; // default: medium
let forceHtml = false;
let forceMd = false;
let tierMode = null; // 'micro', 'standard', 'full'

for (let i = 0; i < args.length; i++) {
  if (args[i] === '--level' && i + 1 < args.length) {
    skeletonLevel = parseInt(args[i + 1], 10);
    if (isNaN(skeletonLevel) || skeletonLevel < 0 || skeletonLevel > 5) {
      console.error('Error: --level must be 0, 1, 2, 3, 4, or 5');
      process.exit(1);
    }
    i++; // skip next arg
  } else if (args[i] === '--tier' && i + 1 < args.length) {
    tierMode = args[i + 1];
    if (!['micro', 'standard', 'full'].includes(tierMode)) {
      console.error('Error: --tier must be micro, standard, or full');
      process.exit(1);
    }
    i++; // skip next arg
  } else if (args[i] === '--html') {
    forceHtml = true;
  } else if (args[i] === '--md') {
    forceMd = true;
  } else if (args[i] === '--hash') {
    skeletonLevel = 5;
  } else if (!args[i].startsWith('--')) {
    filePath = args[i];
  }
}

// Map tier to level
if (tierMode === 'micro') skeletonLevel = 4;
else if (tierMode === 'standard') skeletonLevel = 2;
else if (tierMode === 'full') skeletonLevel = 0;

function getLanguage(filePath) {
  const ext = path.extname(filePath).toLowerCase();
  if (ext === '.py') return 'python';
  if (['.ts', '.tsx', '.js', '.jsx', '.cjs', '.mjs'].includes(ext)) return 'typescript';
  if (ext === '.go') return 'go';
  if (ext === '.java') return 'java';
  if (ext === '.rs') return 'rust';
  if (ext === '.cs') return 'csharp';
  if (ext === '.kt') return 'kotlin';
  if (ext === '.html' || ext === '.htm') return 'html';
  if (ext === '.md' || ext === '.markdown') return 'markdown';
  if (ext === '.css' || ext === '.scss' || ext === '.less') return 'css';
  if (ext === '.json') return 'json';
  if (ext === '.yaml' || ext === '.yml') return 'yaml';
  if (ext === '.xml' || ext === '.svg') return 'xml';
  return 'unknown';
}

// ============================================================
// LEVEL 4 — Ultra (Symbol Table)
// ============================================================
// Output: file:line  name(params)  — no types, no defaults, no decorators
// Example: soul_core.py:97  class CompagentRequest
//          soul_core.py:129 async def get_vitals()
// ============================================================
function processPythonLevel4(content, filePath) {
  const lines = content.split('\n');
  const symbols = [];
  const fileName = path.basename(filePath);

  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];
    const trimmed = line.trim();
    const lineNum = i + 1;

    // Class definitions
    if (trimmed.startsWith('class ')) {
      const name = trimmed.split(/[(:]/)[0].replace('class ', '').trim();
      symbols.push(`${fileName}:${lineNum}  class ${name}`);
      continue;
    }

    // Function definitions
    if (trimmed.startsWith('async def ')) {
      const match = trimmed.match(/async def (\w+)\s*\(([^)]*)\)/);
      if (match) {
        const name = match[1];
        // Strip types and defaults from params — just keep param names
        const params = match[2].split(',').map(p => {
          p = p.trim();
          // Remove type annotations and defaults
          p = p.replace(/:.*$/, '').replace(/=.*$/, '').trim();
          return p;
        }).filter(p => p && p !== 'self' && p !== 'cls');
        const paramStr = params.length ? `(${params.join(', ')})` : '()';
        symbols.push(`${fileName}:${lineNum}  async def ${name}${paramStr}`);
      } else {
        // Fallback: just get the name
        const name = trimmed.replace('async def ', '').split('(')[0].trim();
        symbols.push(`${fileName}:${lineNum}  async def ${name}(...)`);
      }
      continue;
    }

    if (trimmed.startsWith('def ')) {
      const match = trimmed.match(/def (\w+)\s*\(([^)]*)\)/);
      if (match) {
        const name = match[1];
        const params = match[2].split(',').map(p => {
          p = p.trim();
          p = p.replace(/:.*$/, '').replace(/=.*$/, '').trim();
          return p;
        }).filter(p => p && p !== 'self' && p !== 'cls');
        const paramStr = params.length ? `(${params.join(', ')})` : '()';
        symbols.push(`${fileName}:${lineNum}  def ${name}${paramStr}`);
      } else {
        const name = trimmed.replace('def ', '').split('(')[0].trim();
        symbols.push(`${fileName}:${lineNum}  def ${name}(...)`);
      }
      continue;
    }
  }

  return symbols.join('\n');
}

function processCLikeLevel4(content, language, filePath) {
  const lines = content.split('\n');
  const symbols = [];
  const fileName = path.basename(filePath);

  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];
    const trimmed = line.trim();
    const lineNum = i + 1;

    // Skip empty, comments, imports
    if (!trimmed || trimmed.startsWith('//') || trimmed.startsWith('/*') || trimmed.startsWith('*') ||
        trimmed.startsWith('import ') || trimmed.startsWith('package ') || trimmed.startsWith('using ')) {
      continue;
    }

    // Class/interface/enum/struct/record
    const typeMatch = trimmed.match(/(?:export\s+)?(?:abstract\s+|sealed\s+)?(?:class|interface|enum|struct|record|type)\s+(\w+)/);
    if (typeMatch) {
      symbols.push(`${fileName}:${lineNum}  ${typeMatch[0].trim()}`);
      continue;
    }

    // Function/method signatures
    const funcMatch = trimmed.match(/(?:export\s+|public\s+|private\s+|protected\s+|async\s+|static\s+)*(?:function\s+)?(\w+)\s*\(/);
    if (funcMatch && !trimmed.startsWith('if ') && !trimmed.startsWith('for ') && !trimmed.startsWith('while ') && !trimmed.startsWith('switch ')) {
      const name = funcMatch[1];
      const paramsMatch = trimmed.match(/\(([^)]*)\)/);
      let paramStr = '()';
      if (paramsMatch) {
        const params = paramsMatch[1].split(',').map(p => {
          p = p.trim();
          p = p.replace(/:.*$/, '').replace(/=.*$/, '').trim();
          return p;
        }).filter(p => p);
        paramStr = params.length ? `(${params.join(', ')})` : '()';
      }
      symbols.push(`${fileName}:${lineNum}  ${name}${paramStr}`);
      continue;
    }

    // Top-level const/let/var
    const declMatch = trimmed.match(/(?:export\s+)?(?:const|let|var)\s+(\w+)/);
    if (declMatch) {
      symbols.push(`${fileName}:${lineNum}  ${declMatch[0].trim()}`);
      continue;
    }
  }

  return symbols.join('\n');
}

// ============================================================
// LEVEL 5 — Atomic (Hash-based)
// ============================================================
// Output: file:line  #hash
// Full signatures stored in sidecar JSON for on-demand expansion
// ============================================================
function processPythonLevel5(content, filePath) {
  const lines = content.split('\n');
  const atoms = [];
  const fileName = path.basename(filePath);

  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];
    const trimmed = line.trim();
    const lineNum = i + 1;

    if (trimmed.startsWith('class ') || trimmed.startsWith('def ') || trimmed.startsWith('async def ')) {
      const hash = crypto.createHash('md5').update(trimmed).digest('hex').substring(0, 4);
      atoms.push(`${fileName}:${lineNum}  #${hash}`);
    }
  }

  return atoms.join('\n');
}

function processCLikeLevel5(content, language, filePath) {
  const lines = content.split('\n');
  const atoms = [];
  const fileName = path.basename(filePath);

  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];
    const trimmed = line.trim();
    const lineNum = i + 1;

    if (!trimmed || trimmed.startsWith('//') || trimmed.startsWith('/*')) continue;

    const typeMatch = trimmed.match(/(?:export\s+)?(?:abstract\s+|sealed\s+)?(?:class|interface|enum|struct|record|type)\s+(\w+)/);
    const funcMatch = trimmed.match(/(?:export\s+|public\s+|private\s+|protected\s+|async\s+|static\s+)*(?:function\s+)?(\w+)\s*\(/);

    if (typeMatch || (funcMatch && !trimmed.startsWith('if ') && !trimmed.startsWith('for ') && !trimmed.startsWith('while '))) {
      const hash = crypto.createHash('md5').update(trimmed).digest('hex').substring(0, 4);
      atoms.push(`${fileName}:${lineNum}  #${hash}`);
    }
  }

  return atoms.join('\n');
}

function processPython(content, level) {
  const lines = content.split('\n');
  const skeleton = [];
  let inDocstring = false;
  let docstringChar = '';

  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];
    const trimmed = line.trim();

    // Level 0: return full content
    if (level === 0) {
      skeleton.push(line);
      continue;
    }

    // Handle docstrings
    if (!inDocstring && (trimmed.startsWith('"""') || trimmed.startsWith("'''"))) {
      inDocstring = true;
      docstringChar = trimmed.substring(0, 3);
      if (level <= 1) skeleton.push(line); // light: keep docstrings
      if (trimmed.length > 3 && trimmed.endsWith(docstringChar)) {
        inDocstring = false;
      }
      continue;
    }
    if (inDocstring) {
      if (trimmed.endsWith(docstringChar) && trimmed.length >= 3) {
        inDocstring = false;
        if (level <= 1) skeleton.push(line);
      }
      continue;
    }

    // Keep imports (all levels >= 1)
    if (trimmed.startsWith('import ') || trimmed.startsWith('from ')) {
      skeleton.push(line);
      continue;
    }

    // Keep decorators (level 1-2)
    if (trimmed.startsWith('@')) {
      if (level <= 2) skeleton.push(line);
      continue;
    }

    // Keep class and def
    if (trimmed.startsWith('class ') || trimmed.startsWith('def ') || trimmed.startsWith('async def ')) {
      let sig = line;
      let j = i;
      while (!sig.includes(':') && j < lines.length - 1) {
        j++;
        sig += ' ' + lines[j].trim();
      }
      i = j;
      if (level <= 2) {
        skeleton.push(sig + ' ...');
      } else {
        skeleton.push(sig);
      }
      continue;
    }

    // Keep top-level assignments (level 1-2)
    if (level <= 2 && !line.startsWith(' ') && !line.startsWith('\t') && trimmed.includes('=') && !trimmed.startsWith('if ') && !trimmed.startsWith('for ')) {
      skeleton.push(line);
      continue;
    }

    // Level 1: keep all non-empty, non-comment lines
    if (level === 1 && trimmed !== '' && !trimmed.startsWith('#')) {
      skeleton.push(line);
    }
  }
  return skeleton.join('\n');
}

function processCLike(content, language, level) {
  const lines = content.split('\n');
  const skeleton = [];
  let depth = 0;

  // Level 0: return full content
  if (level === 0) return content;

  // Regex to detect signatures
  const isSignature = (str) => {
    if (str.startsWith('import ') || str.startsWith('package ') || str.startsWith('using ')) return true;
    if (str.startsWith('@') || str.startsWith('[')) return true;
    if (str.includes('class ') || str.includes('interface ') || str.includes('enum ') || str.includes('struct ') || str.includes('type ') || str.includes('record ')) return true;

    if (str.match(/(public\s+|private\s+|protected\s+|async\s+)*[\w<>\[\]]+\s+\w+\s*\(/) || str.match(/func\s+\w+\s*\(/) || str.match(/fn\s+\w+\s*\(/) || str.match(/fun\s+\w+\s*\(/)) {
      return true;
    }

    if (str.includes(' { get;') || str.includes(' { get ')) return true;

    if ((depth === 0 || depth === 1) && (str.includes('const ') || str.includes('let ') || str.includes('var ') || str.includes('val '))) {
      return true;
    }

    return false;
  };

  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];
    const trimmed = line.trim();

    // Level 1: keep comments
    if (level === 1 && (trimmed.startsWith('//') || trimmed.startsWith('/*') || trimmed.startsWith('*'))) {
      skeleton.push(line);
      continue;
    }

    if (trimmed === '' || trimmed.startsWith('//') || trimmed.startsWith('/*')) {
      continue;
    }

    const openBraces = (line.match(/\{/g) || []).length;
    const closeBraces = (line.match(/\}/g) || []).length;

    let kept = false;

    if (isSignature(trimmed) && depth <= 1) {
      if (trimmed.endsWith('{')) {
        skeleton.push(line + ' /* ... */ }');
      } else {
        skeleton.push(line);
      }
      kept = true;
    } else if (openBraces > 0 && depth === 0) {
      skeleton.push(line);
      kept = true;
    } else if (closeBraces > 0 && depth === 1) {
      skeleton.push(line);
      kept = true;
    }

    // Level 1: keep all non-empty lines
    if (level === 1 && !kept && trimmed !== '') {
      skeleton.push(line);
    }

    depth += openBraces;
    depth -= closeBraces;
    if (depth < 0) depth = 0;
  }

  return skeleton.join('\n');
}

function processHTML(content, level) {
  const lines = content.split('\n');
  const skeleton = [];

  // Level 0: return full content
  if (level === 0) return content;

  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];
    const trimmed = line.trim();

    // Skip empty lines and HTML comments
    if (trimmed === '' || trimmed.startsWith('<!--')) continue;

    // === ALWAYS KEPT (all levels) ===
    // DOCTYPE, html/head/body wrappers
    if (trimmed.startsWith('<!') || trimmed.startsWith('<html') || trimmed.startsWith('</html>') ||
        trimmed.startsWith('<head') || trimmed.startsWith('</head>') ||
        trimmed.startsWith('<body') || trimmed.startsWith('</body>')) {
      skeleton.push(line);
      continue;
    }

    // Title, meta, link tags (resource references)
    if (trimmed.startsWith('<title') || trimmed.startsWith('</title>') ||
        trimmed.startsWith('<meta') || trimmed.startsWith('<link')) {
      skeleton.push(line);
      continue;
    }

    // Script tags (keep opening/closing, strip body at level 2+)
    if (trimmed.startsWith('<script') || trimmed.startsWith('</script>')) {
      skeleton.push(line);
      continue;
    }

    // === STRUCTURAL TAGS (keep with class/id, strip inline text at level 2+) ===
    const structuralTagMatch = trimmed.match(/^<(\/)?(div|section|nav|header|footer|main|aside|article|form|table|thead|tbody|tfoot|tr|th|td|ul|ol|li|dl|dt|dd|span|p|h[1-6]|figure|figcaption|details|summary)([\s>])/);
    if (structuralTagMatch) {
      const isClosing = !!structuralTagMatch[1];
      const tagName = structuralTagMatch[2];

      if (isClosing) {
        skeleton.push(`</${tagName}>`);
        continue;
      }

      // Extract class and id only (strip all other attributes at level 2+)
      if (level >= 2) {
        const clsMatch = trimmed.match(/class="([^"]*)"/);
        const idMatch = trimmed.match(/id="([^"]*)"/);
        let attrStr = '';
        if (idMatch) attrStr += ` id="${idMatch[1]}"`;
        if (clsMatch) attrStr += ` class="${clsMatch[1]}"`;
        skeleton.push(`<${tagName}${attrStr}>`);
      } else {
        skeleton.push(line);
      }
      continue;
    }

    // === INPUT/FORM ELEMENTS (keep with id/name/type) ===
    const inputMatch = trimmed.match(/^<(input|select|textarea|button|label|option|fieldset|legend)([\s>])/);
    if (inputMatch) {
      if (level >= 2) {
        const idMatch = trimmed.match(/id="([^"]*)"/);
        const nameMatch = trimmed.match(/name="([^"]*)"/);
        const typeMatch = trimmed.match(/type="([^"]*)"/);
        let attrStr = '';
        if (idMatch) attrStr += ` id="${idMatch[1]}"`;
        if (nameMatch) attrStr += ` name="${nameMatch[1]}"`;
        if (typeMatch) attrStr += ` type="${typeMatch[1]}"`;
        skeleton.push(`<${inputMatch[1]}${attrStr}>`);
      } else {
        skeleton.push(line);
      }
      continue;
    }

    // === IMG/VIDEO/AUDIO/SOURCE (keep with src) ===
    const mediaMatch = trimmed.match(/^<(img|video|audio|source|canvas|iframe|embed|object)([\s>])/);
    if (mediaMatch) {
      if (level >= 2) {
        const srcMatch = trimmed.match(/src="([^"]*)"/);
        const altMatch = trimmed.match(/alt="([^"]*)"/);
        let attrStr = '';
        if (srcMatch) attrStr += ` src="${srcMatch[1]}"`;
        if (altMatch) attrStr += ` alt="${altMatch[1]}"`;
        skeleton.push(`<${mediaMatch[1]}${attrStr}>`);
      } else {
        skeleton.push(line);
      }
      continue;
    }

    // === STYLE TAG (keep opening/closing, strip body at level 2+) ===
    if (trimmed.startsWith('<style') || trimmed.startsWith('</style>')) {
      skeleton.push(line);
      continue;
    }

    // === TEMPLATE/SLOT/WEB COMPONENT TAGS ===
    const wcMatch = trimmed.match(/^<(\/)?([a-z]+-[a-z]+)([\s>])/);
    if (wcMatch) {
      skeleton.push(line);
      continue;
    }

    // === LEVEL 1: keep all non-empty lines (light) ===
    if (level === 1) {
      skeleton.push(line);
      continue;
    }

    // === LEVEL 2: medium — keep only structural lines with data/aria/events ===
    // Lines with data attributes, aria attributes, or event handlers
    if (level === 2 && trimmed.match(/(data-[a-z]+|aria-[a-z]+|onclick|onchange|onsubmit)="[^"]*"/)) {
      skeleton.push(line);
      continue;
    }

    // Lines with template literals or JSX-like content (level 2 only)
    if (level === 2 && (trimmed.includes('${') || trimmed.includes('{/*'))) {
      skeleton.push(line);
      continue;
    }

    // Level 2: also keep lines that are pure text content (non-empty, non-tag)
    // This catches inline text between tags
    if (level === 2 && !trimmed.startsWith('<') && trimmed !== '') {
      skeleton.push(line);
      continue;
    }

    // Level 3: strip everything not already kept (deep)
    // Level 3 only keeps what was matched above — no extra catches
  }
  return skeleton.join('\n');
}

function processMarkdown(content, level) {
  const lines = content.split('\n');
  const skeleton = [];

  // Level 0: return full content
  if (level === 0) return content;

  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];
    const trimmed = line.trim();

    // Always keep: headings, code blocks, tables, lists, blockquotes, horizontal rules
    if (trimmed.startsWith('#') || trimmed.startsWith('```') || trimmed.startsWith('|') ||
        trimmed.startsWith('- ') || trimmed.startsWith('* ') || trimmed.startsWith('> ') ||
        trimmed.startsWith('---') || trimmed.startsWith('***') || trimmed.startsWith('___')) {
      skeleton.push(line);
      continue;
    }

    // Keep links and references
    if (trimmed.match(/\[.+\]\(.+\)/) || trimmed.match(/^\[.+\]:/)) {
      skeleton.push(line);
      continue;
    }

    // Keep bold/italic text
    if (trimmed.match(/\*\*.*\*\*/) || trimmed.match(/__.*__/) || trimmed.match(/\*.*\*/) || trimmed.match(/_.*_/)) {
      skeleton.push(line);
      continue;
    }

    // Level 1-2: keep all non-empty lines
    if (level <= 2 && trimmed !== '') {
      skeleton.push(line);
    }
  }
  return skeleton.join('\n');
}

function processCSS(content, level) {
  const lines = content.split('\n');
  const skeleton = [];

  if (level === 0) return content;

  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];
    const trimmed = line.trim();

    // Keep selectors and opening braces
    if (trimmed.endsWith('{') || trimmed.startsWith('@') || trimmed.startsWith('.')) {
      skeleton.push(line);
      continue;
    }

    // Keep closing braces
    if (trimmed === '}') {
      skeleton.push(line);
      continue;
    }

    // Level 1-2: keep all non-empty lines
