          break;
        case 'typescript':
        case 'go':
        case 'java':
        case 'rust':
        case 'csharp':
        case 'kotlin':
          skeleton = processCLikeLevel5(content, lang, filePath);
          break;
        default:
          skeleton = processPython(content, 3);
      }
    } else {
      // Levels 0-3 use existing processors
      switch (lang) {
        case 'python':
          skeleton = processPython(content, skeletonLevel);
          break;
        case 'html':
          skeleton = processHTML(content, skeletonLevel);
          break;
        case 'markdown':
          skeleton = processMarkdown(content, skeletonLevel);
