    const levelNames = ['full', 'light', 'medium', 'deep', 'ultra', 'atomic'];
    const header = `// ${fileName} (${originalLines} lines → ${skeletonLines}-line skeleton, level=${levelNames[skeletonLevel]})`;

    console.log(`[TokenSlayer Saved ${reduction}% (${originalTokens} -> ${compactedTokens} tokens)]\n`);
    console.log(header);
    console.log('');
    if (skeleton) {
      console.log(skeleton);
    } else {
      console.log('// (empty skeleton — no symbols found)');
    }

  } catch (err) {
    console.error(`Error processing file: ${err.message}`);
    process.exit(1);
  }
}

// Main
if (!filePath) {
  console.error('Usage: node tokenslayer.js <filepath> [--level 0-5] [--tier micro|standard|full] [--html] [--md]');
  process.exit(1);
}

