  ];

  const DROP = [
    // Private decorators
    '@_internal_helper',
    '@__dunder_decorator__',
    // Random unqualified short names not on the allow-list
    '@helper',
    '@my_decorator',
    '@some_random_thing',
  ];

  for (const d of KEEP) {
    test(`keeps ${d}`, () => {
      assert.equal(PythonCompactor.isSignificantDecorator(d), true,
        `expected to KEEP ${d}`);
