      ${item.conditionsOfUse ? this._renderConditionsOfUse(item.conditionsOfUse) : ''}
      <div style="margin-top:16px;padding:12px;background:rgba(0,229,255,0.05);border-radius:8px;border:1px solid rgba(0,229,255,0.15)">
