                { axis: 'y', freq: 0.125, amp: 0.005 }, // follows weight shift
            ],
            rightShoulder: [
                { axis: 'z', freq: 0.09, amp: -0.01, phase: Math.PI * 0.7 }, // async
                { axis: 'x', freq: 0.18, amp: 0.006, phase: 0.6 }, // rises with breath (leads arm)
