                watsonx: {
                    api_key: '',
                    project_id: '',
                    model_id: 'ibm/granite-13b-chat-v2',
                    base_url: 'https://us-south.ml.cloud.ibm.com',
                },
                ollama: {
                    base_url: 'http://localhost:11434',
                    model: 'llama3',
                },
                ollabridge: {
                    api_key: '',
                    pair_token: '',
                    auth_mode: 'pairing',
                    base_url: '',
                    model: 'default',
                    use_remote_prompt: true,
                },
            };
        }

        // ===============================================
        // OllaBridge Pairing
        // ===============================================

        /**
         * Exchange a pairing code for a persistent bearer token from OllaBridge.
         * The returned token is stored in settings.ollabridge.pair_token and persisted.
         *
         * @param {string} code - The 6-digit pairing code from the OllaBridge console
         * @param {string} [label] - Friendly device label (default: '3d-avatar')
         * @returns {Promise<{ok: boolean, token?: string, device_id?: string, error?: string}>}
         */
        async pairWithOllaBridge(code, label = '3d-avatar') {
            const cfg = this._settings.ollabridge || {};
            const base_url = (cfg.base_url || '').replace(/\/$/, '');

            if (!base_url) {
                return {
                    ok: false,
                    error: 'Missing OllaBridge Base URL. Enter it in Settings (e.g. http://localhost:11435 or https://ruslanmv-ollabridge.hf.space).',
                };
            }

            const url = `${base_url}/pair`;

            try {
                let res;
                const headers = { 'Content-Type': 'application/json' };
                const cleanCode = String(code || '')
                    .trim()
                    .toUpperCase()
                    .replace(/-/g, '')
                    .replace(/\s+/g, '');
                const payload = { code: cleanCode, label };

                if (this._hasProxy()) {
                    res = await this._fetchViaProxy(url, 'POST', headers, payload);
                } else {
                    res = await fetch(url, {
                        method: 'POST',
                        headers,
                        body: JSON.stringify(payload),
                    });
                }

                const text = await res.text();

                if (!res.ok) {
                    return { ok: false, error: `Pairing failed: ${res.status} - ${text}` };
                }

                let data;
                try {
                    data = JSON.parse(text);
                } catch {
                    return { ok: false, error: `Unexpected non-JSON response from OllaBridge: ${text}` };
                }

                if (data?.ok && data?.token) {
                    // Store the paired token in settings
                    this._settings.ollabridge.pair_token = data.token;
                    if (data.device_id) {
                        this._settings.ollabridge.device_id = data.device_id;
                    }
                    this._saveSettings();
                    return { ok: true, token: data.token, device_id: data.device_id || null };
                }

                // Server returned a structured error — surface it directly
                if (data?.error) {
                    return { ok: false, error: data.error };
                }

                return { ok: false, error: `Unexpected response from OllaBridge: ${JSON.stringify(data)}` };
            } catch (e) {
                const hint =
                    e.message && e.message.includes('Failed to fetch')
                        ? '. This is likely a CORS issue — ensure OllaBridge has CORS_ORIGINS configured for this origin, or run the proxy server.'
                        : '';
                return { ok: false, error: `Cannot reach OllaBridge: ${e.message}${hint}` };
            }
        }

        /**
         * Fetch OllaBridge auth mode info from /pair/info endpoint.
         * Returns which authentication modes are available.
         *
         * @returns {Promise<{auth_mode: string, pairing_enabled: boolean, pairing_available: boolean, device_count: number, error?: string}>}
         */
        async getOllaBridgeAuthInfo() {
            const base_url = (this._settings.ollabridge?.base_url || '').replace(/\/$/, '');

            if (!base_url) {
                return {
                    auth_mode: 'pairing',
                    pairing_enabled: false,
                    pairing_available: false,
                    device_count: 0,
                    error: 'Missing OllaBridge Base URL',
                };
            }

            const url = `${base_url}/pair/info`;

            try {
                let res;
                if (this._hasProxy()) {
                    res = await this._fetchViaProxy(url, 'GET', {}, null);
                } else {
                    res = await fetch(url);
                }

                if (!res.ok) {
                    return {
                        auth_mode: 'unknown',
                        pairing_enabled: false,
                        pairing_available: false,
                        device_count: 0,
                        error: `HTTP ${res.status}`,
                    };
                }

                const data = await res.json();
                return {
                    auth_mode: data.auth_mode || 'required',
                    pairing_enabled: data.pairing_enabled || false,
                    pairing_available: data.pairing_available || false,
                    device_count: data.device_count || 0,
                    ttl_remaining: data.ttl_remaining || 0,
                    code_display: data.code_display || '',
                };
            } catch (e) {
                return {
                    auth_mode: 'unknown',
                    pairing_enabled: false,
                    pairing_available: false,
                    device_count: 0,
                    error: e.message,
                };
            }
        }

        // ===============================================
        // Utilities
        // ===============================================

        _deepMerge(target, source) {
            const output = Object.assign({}, target);
            if (this._isObject(target) && this._isObject(source)) {
                Object.keys(source).forEach((key) => {
                    if (this._isObject(source[key])) {
                        if (!(key in target)) {
                            Object.assign(output, { [key]: source[key] });
                        } else {
                            output[key] = this._deepMerge(target[key], source[key]);
                        }
                    } else {
                        Object.assign(output, { [key]: source[key] });
                    }
                });
            }
            return output;
        }

        _isObject(item) {
            return item && typeof item === 'object' && !Array.isArray(item);
        }
    }

    // ===============================================
    // Expose to global scope
    // ===============================================
    global.LLMManager = LLMManager;
    global.LLMProvider = LLMProvider;
})(window);

