         * @returns {Promise<string>} Response text
         */
        async sendToSoul(message, options = {}) {
            try {
                const response = await fetch(`${SOUL_CORE_URL}/compagent`, {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
