         */
        async streamFromSoul(message, onToken, onMotor, onDone) {
            try {
                const response = await fetch(`${SOUL_CORE_URL}/compagent/stream`, {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
