    function applyPortraitPose(root, options = {}) {
        return normalizeAvatarPose(root, { ...options, preset: 'portrait' });
    }

    function applyThumbnailPose(root, options = {}) {
        return normalizeAvatarPose(root, { ...options, preset: 'portrait' });
    }

