        normalizeAvatarPose,
        applyRelaxedStandingPose,
        applyPortraitPose,
        applyThumbnailPose,
        applyPresentationPose,
        restoreNeutralPose,
        snapshotOriginalPose,
        buildRigMap,
        getSettings,
        updateSettings,
        resetSettings,
        getDefaultSettings,
        PRESETS,
    };

    console.log('[PoseNormalizer] Module loaded');
})();

