        captureFromRig: function (rigMap, neutralPose) {
            var bones = {};
            var keys = Object.keys(rigMap.bones);

            for (var i = 0; i < keys.length; i++) {
                var key = keys[i];
                var bone = rigMap.bones[key];
                if (!bone) continue;

