            const idx = Math.floor(phase * 0.7) % visemes.length;
            const intensity = 0.2 + t * 0.5; // 0.2..0.7 range — not too exaggerated

            // Reset all mouth visemes, then set active one
            for (const v of visemes) {
                try {
