        } else if (label === SEMANTIC.WALL) {
            this.walls.set(plane, data);
        } else if (
            label === SEMANTIC.TABLE ||
            label === SEMANTIC.COUCH ||
            label === SEMANTIC.DOOR ||
            label === SEMANTIC.WINDOW
        ) {
            this.furniture.set(plane, data);
        }

