    }

    /**
     * @param {import('ratk').Plane} plane
     */
    _handlePlaneRemoved(plane) {
        const data = this.allPlanes.get(plane);
        if (!data) return;

        this.allPlanes.delete(plane);
        this.floors.delete(plane);
        this.walls.delete(plane);
