    _statusLabel() {
        switch (this.status) {
            case 'listening':
                return 'LISTENING';
            case 'thinking':
                return 'THINKING';
            case 'speaking':
                return 'SPEAKING';
            default:
                return 'READY';
        }
    }

    _statusColor() {
        switch (this.status) {
            case 'listening':
                return 'rgba(255, 95, 95, 0.95)';
            case 'thinking':
                return this.theme.accent;
            case 'speaking':
                return 'rgba(140, 255, 180, 0.95)';
            default:
                return this.theme.textDim;
        }
    }

    _roundRect(ctx, x, y, w, h, r) {
        const rr = Math.min(r, w / 2, h / 2);
        ctx.beginPath();
        ctx.moveTo(x + rr, y);
        ctx.arcTo(x + w, y, x + w, y + h, rr);
        ctx.arcTo(x + w, y + h, x, y + h, rr);
        ctx.arcTo(x, y + h, x, y, rr);
        ctx.arcTo(x, y, x + w, y, rr);
        ctx.closePath();
    }

    _wrapText(ctx, text, x, y, maxX, lineHeight) {
        const words = String(text || '').split(/\s+/);
        let line = '';
        let yy = y;

        for (let i = 0; i < words.length; i++) {
            const test = `${line + words[i]} `;
            if (ctx.measureText(test).width > maxX - x && i > 0) {
                ctx.fillText(line, x, yy);
                line = `${words[i]} `;
                yy += lineHeight;
            } else {
                line = test;
            }
        }
        ctx.fillText(line, x, yy);
        return yy;
    }

    // =====================================================================
    // CLICK HANDLERS (called from your VRChatIntegration / onUIButtonClick)
    // =====================================================================

    /**
     * Optional helper: call this from your UI click handler.
     * Example:
     *   if (panel.handleUIAction(mesh.name, mesh.userData)) return;
     */
    handleUIAction(name, userData = {}) {
        const key = userData?.key;

        // ─── Mode guard (defense-in-depth) ───
        // Reject clicks from hitboxes that belong to an inactive mode.
        // This is the last safety net — the primary filter is in VRControllers
        // (only active interactables are raycasted). This catches edge cases like
        // rapid mode switches where the raycast list hasn't updated yet.
        const hitMode = userData?.mode;
        if (hitMode && hitMode !== 'global' && hitMode !== this.mode) {
            return false;
        }

