            return true;
        }

        return false;
    }

    // =====================================================================
    // DISPOSE
    // =====================================================================

    dispose() {
        try {
            this.texture?.dispose?.();
        } catch (_) {}
        this.group.traverse((o) => {
            try {
                o.geometry?.dispose?.();
            } catch (_) {}
            try {
                o.material?.dispose?.();
