     * Get a resolved bone by humanoid key.
     * @param {string} boneKey — humanoid bone key (e.g. 'leftHand', 'hips')
     * @returns {THREE.Bone|null}
     */
    getBone(boneKey) {
        return this._bones.get(boneKey) || null;
