describe('PoseNormalizer', () => {
    test('should be exposed on window', () => {
        expect(window.NEXUS_POSE_NORMALIZER).toBeDefined();
        expect(typeof window.NEXUS_POSE_NORMALIZER.normalizeAvatarPose).toBe('function');
