    test('should start in IDLE state', () => {
        window.NEXUS_BEHAVIOR.setState('IDLE');
        expect(window.NEXUS_BEHAVIOR.getState()).toBe('IDLE');
    });

    test('should transition IDLE → THINKING on user message', () => {
