  if (!btn) return;
  if (_stackRunning) {
    btn.textContent = '⏹ Stop LUMAX Stack';
    btn.className = 'btn btn-stop';
    btn.style.fontSize = '16px';
    btn.style.padding = '12px';
  } else {
