                <button id="btn-thoughts-new-session" style="background: rgba(0,243,255,0.1); border: 1px solid var(--neon-blue); color: #fff; padding: 6px 12px; cursor: pointer; border-radius: 4px; font-family: 'Orbitron'; font-size: 0.6rem;">
