                </button>
            </div>
            <div id="thoughts-list" style="flex: 1; overflow-y: auto; display: flex; flex-direction: column; gap: 8px;">
        `;

        if (thoughts.length === 0) {
            html += `
                <div style="text-align: center; padding: 40px; opacity: 0.5;">
