/**
 * TokenSlayerTab — WebUI Operations tab for TokenSlayer stats & settings.
 * Polls the TokenSlayer Dashboard API (port 8104) for aggregate statistics.
 */
export class TokenSlayerTab {
    private static pollInterval: ReturnType<typeof setInterval> | null = null;
    private static container: HTMLElement | null = null;

    public static async render(container: HTMLElement): Promise<void> {
        TokenSlayerTab.container = container;
        container.innerHTML = TokenSlayerTab.buildHTML();
        TokenSlayerTab.setupInteractions(container);
        await TokenSlayerTab.fetchStats();
        // Poll every 10s
        if (TokenSlayerTab.pollInterval) clearInterval(TokenSlayerTab.pollInterval);
        TokenSlayerTab.pollInterval = setInterval(() => TokenSlayerTab.fetchStats(), 10000);
    }

    public static destroy(): void {
        if (TokenSlayerTab.pollInterval) {
            clearInterval(TokenSlayerTab.pollInterval);
            TokenSlayerTab.pollInterval = null;
        }
        TokenSlayerTab.container = null;
    }

    private static buildHTML(): string {
        return `
            <div class="ts-tab" style="padding: 16px; overflow-y: auto; height: 100%;">
                <div class="breadcrumb" style="font-family:'Share Tech Mono',monospace; font-size:0.65rem; color:var(--neon-blue); letter-spacing:1px; margin-bottom:16px;">
                    TOKENSLAYER // CONTEXT_COMPRESSION_ENGINE
                </div>

                <!-- Stats Cards -->
                <div class="ts-cards" style="display:grid; grid-template-columns:repeat(auto-fit, minmax(160px, 1fr)); gap:12px; margin-bottom:20px;">
                    <div class="glass-card" style="padding:14px; text-align:center;">
                        <div style="font-size:0.6rem; color:#8b949e; text-transform:uppercase; letter-spacing:1px;">Files Processed</div>
                        <div id="ts-stat-files" class="ts-stat-value" style="font-size:1.8rem; font-weight:700; color:#58a6ff; margin-top:4px;">—</div>
                    </div>
                    <div class="glass-card" style="padding:14px; text-align:center;">
                        <div style="font-size:0.6rem; color:#8b949e; text-transform:uppercase; letter-spacing:1px;">Tokens Saved</div>
                        <div id="ts-stat-saved" class="ts-stat-value" style="font-size:1.8rem; font-weight:700; color:#3fb950; margin-top:4px;">—</div>
                    </div>
                    <div class="glass-card" style="padding:14px; text-align:center;">
                        <div style="font-size:0.6rem; color:#8b949e; text-transform:uppercase; letter-spacing:1px;">Compression Rate</div>
                        <div id="ts-stat-pct" class="ts-stat-value" style="font-size:1.8rem; font-weight:700; color:#3fb950; margin-top:4px;">—</div>
                    </div>
                    <div class="glass-card" style="padding:14px; text-align:center;">
                        <div style="font-size:0.6rem; color:#8b949e; text-transform:uppercase; letter-spacing:1px;">Est. Cost Saved</div>
                        <div id="ts-stat-cost" class="ts-stat-value" style="font-size:1.8rem; font-weight:700; color:#d2991d; margin-top:4px;">—</div>
                    </div>
                </div>

                <!-- Language Breakdown -->
                <div class="glass-card" style="padding:14px; margin-bottom:16px;">
                    <div style="font-size:0.65rem; color:#8b949e; text-transform:uppercase; letter-spacing:1px; margin-bottom:10px;">Language Breakdown</div>
                    <div id="ts-lang-table" style="font-size:0.7rem;">
                        <div style="color:#484f58; text-align:center; padding:20px;">Loading stats from TokenSlayer Dashboard (port 8104)...</div>
                    </div>
                </div>

                <!-- Recent Activity -->
                <div class="glass-card" style="padding:14px; margin-bottom:16px;">
                    <div style="font-size:0.65rem; color:#8b949e; text-transform:uppercase; letter-spacing:1px; margin-bottom:10px;">Recent Invocations</div>
                    <div id="ts-history-table" style="font-size:0.65rem; max-height:300px; overflow-y:auto;">
                        <div style="color:#484f58; text-align:center; padding:20px;">No invocations logged yet.</div>
                    </div>
                </div>

                <!-- Settings & Actions -->
                <div class="glass-card" style="padding:14px; margin-bottom:16px;">
                    <div style="font-size:0.65rem; color:#8b949e; text-transform:uppercase; letter-spacing:1px; margin-bottom:10px;">Settings & Actions</div>
                    <div style="display:flex; flex-wrap:wrap; gap:8px;">
                        <button id="ts-btn-dashboard" class="btn btn-dev" style="padding:8px 16px; font-size:0.65rem;">
                            🌐 Open Dashboard
                        </button>
                        <button id="ts-btn-refresh" class="btn btn-dev" style="padding:8px 16px; font-size:0.65rem;">
                            ⟳ Refresh Stats
                        </button>
                        <button id="ts-btn-reset" class="btn btn-dev" style="padding:8px 16px; font-size:0.65rem; color:#ff007f; border-color:#ff007f33;">
                            🗑 Reset Stats
                        </button>
                    </div>
                    <div id="ts-msg" style="font-size:0.6rem; color:#8b949e; margin-top:8px; min-height:16px;"></div>
                </div>

                <!-- API Info -->
                <div class="glass-card" style="padding:14px; opacity:0.7;">
                    <div style="font-size:0.6rem; color:#8b949e; line-height:1.6;">
                        <strong style="color:#7ee787;">TokenSlayer API</strong> — Port 8104<br>
                        <code style="background:#0d1117; padding:2px 6px; border-radius:3px; font-size:0.6rem; color:#7ee787;">GET /api/stats</code> — aggregate statistics<br>
                        <code style="background:#0d1117; padding:2px 6px; border-radius:3px; font-size:0.6rem; color:#7ee787;">POST /api/log</code> — log invocation<br>
                        <span style="color:#d2991d;">Cost model: DeepSeek V4 ($0.14/M tokens)</span>
                    </div>
                </div>
            </div>
        `;
    }

    private static setupInteractions(container: HTMLElement): void {
        container.querySelector('#ts-btn-refresh')?.addEventListener('click', () => TokenSlayerTab.fetchStats());
        container.querySelector('#ts-btn-dashboard')?.addEventListener('click', () => {
            window.open('http://localhost:8104', '_blank');
        });
        container.querySelector('#ts-btn-reset')?.addEventListener('click', async () => {
            if (!confirm('Reset all TokenSlayer statistics? This cannot be undone.')) return;
            try {
                const resp = await fetch('http://localhost:8104/api/reset', { method: 'POST' });
                if (resp.ok) {
                    TokenSlayerTab.setMsg('Stats reset successfully.', '#3fb950');
                    await TokenSlayerTab.fetchStats();
                } else {
                    TokenSlayerTab.setMsg('Reset failed — endpoint may not support reset.', '#ff007f');
                }
            } catch {
                TokenSlayerTab.setMsg('Cannot reach TokenSlayer Dashboard (port 8104).', '#ff007f');
            }
        });
    }

    private static async fetchStats(): Promise<void> {
        try {
            const resp = await fetch('http://localhost:8104/api/stats', { signal: AbortSignal.timeout(3000) });
            if (!resp.ok) throw new Error(`HTTP ${resp.status}`);
            const data = await resp.json();
            TokenSlayerTab.updateStats(data);
            TokenSlayerTab.setMsg('Connected • Port 8104', '#3fb950');
        } catch {
            TokenSlayerTab.setMsg('TokenSlayer Dashboard offline (port 8104)', '#ff007f');
            TokenSlayerTab.showOffline();
        }
    }

    private static updateStats(data: any): void {
        const totalFiles = data.totalFiles || 0;
        const totalOrig = data.totalOrig || 0;
        const totalSaved = data.totalSaved || 0;
        const saved = totalOrig - totalSaved;
        const pct = totalOrig > 0 ? Math.round((saved / totalOrig) * 100) : 0;
        const costPerM = 0.14;
        const costSaved = ((saved / 1_000_000) * costPerM).toFixed(4);

        TokenSlayerTab.setText('ts-stat-files', totalFiles.toLocaleString());
        TokenSlayerTab.setText('ts-stat-saved', saved.toLocaleString());
        TokenSlayerTab.setText('ts-stat-pct', `${pct}%`);
        TokenSlayerTab.setText('ts-stat-cost', `$${costSaved}`);

        // Language breakdown
        const byLang = data.byLang || {};
        const langEntries = Object.entries(byLang) as [string, { files: number; orig: number; saved: number }][];
        const langTable = document.getElementById('ts-lang-table');
        if (langTable) {
            if (langEntries.length === 0) {
                langTable.innerHTML = '<div style="color:#484f58; text-align:center; padding:20px;">No language data yet. Run TokenSlayer on some files!</div>';
            } else {
                const sorted = langEntries.sort((a, b) => b[1].files - a[1].files);
                let rows = '';
                sorted.forEach(([lang, stats]) => {
                    const langSaved = stats.orig - stats.saved;
                    const langPct = stats.orig > 0 ? Math.round((langSaved / stats.orig) * 100) : 0;
                    rows += `
                        <tr style="border-bottom:1px solid #21262d;">
                            <td style="padding:6px 8px; color:#58a6ff; font-weight:600;">${TokenSlayerTab.escapeHtml(lang)}</td>
                            <td style="padding:6px 8px; text-align:right;">${stats.files}</td>
                            <td style="padding:6px 8px; text-align:right; color:#8b949e;">${stats.orig.toLocaleString()}</td>
                            <td style="padding:6px 8px; text-align:right; color:#8b949e;">${stats.saved.toLocaleString()}</td>
                            <td style="padding:6px 8px; text-align:right; color:#3fb950;">${langPct}%</td>
                        </tr>
                    `;
                });
                langTable.innerHTML = `
                    <table style="width:100%; border-collapse:collapse; font-size:0.65rem;">
                        <thead>
                            <tr style="color:#8b949e; text-transform:uppercase; font-size:0.55rem; letter-spacing:0.5px;">
                                <th style="text-align:left; padding:6px 8px; border-bottom:1px solid #30363d;">Language</th>
                                <th style="text-align:right; padding:6px 8px; border-bottom:1px solid #30363d;">Files</th>
                                <th style="text-align:right; padding:6px 8px; border-bottom:1px solid #30363d;">Orig</th>
                                <th style="text-align:right; padding:6px 8px; border-bottom:1px solid #30363d;">Skel</th>
                                <th style="text-align:right; padding:6px 8px; border-bottom:1px solid #30363d;">Save%</th>
                            </tr>
                        </thead>
                        <tbody>${rows}</tbody>
                    </table>
                `;
            }
        }

        // History
        const history = data.history || [];
        const historyTable = document.getElementById('ts-history-table');
        if (historyTable) {
            if (history.length === 0) {
                historyTable.innerHTML = '<div style="color:#484f58; text-align:center; padding:20px;">No invocations logged yet.</div>';
            } else {
                let rows = '';
                history.slice(0, 30).forEach((h: any) => {
                    const hSaved = h.orig - h.saved;
                    const hPct = h.orig > 0 ? Math.round((hSaved / h.orig) * 100) : 0;
                    const time = h.time ? new Date(h.time).toLocaleTimeString() : '—';
                    const fileShort = (h.file || '').split(/[\\/]/).pop() || h.file || '—';
                    rows += `
                        <tr style="border-bottom:1px solid #21262d;">
                            <td style="padding:4px 6px; color:#8b949e; font-size:0.6rem;">${time}</td>
                            <td style="padding:4px 6px; color:#c9d1d9; max-width:200px; overflow:hidden; text-overflow:ellipsis; white-space:nowrap;" title="${TokenSlayerTab.escapeHtml(h.file || '')}">${TokenSlayerTab.escapeHtml(fileShort)}</td>
                            <td style="padding:4px 6px; color:#58a6ff; text-align:right;">${h.lang || '—'}</td>
                            <td style="padding:4px 6px; color:#8b949e; text-align:right;">${h.orig}</td>
                            <td style="padding:4px 6px; color:#8b949e; text-align:right;">${h.saved}</td>
                            <td style="padding:4px 6px; color:#3fb950; text-align:right;">${hPct}%</td>
                        </tr>
                    `;
                });
                historyTable.innerHTML = `
                    <table style="width:100%; border-collapse:collapse; font-size:0.6rem;">
                        <thead>
                            <tr style="color:#8b949e; text-transform:uppercase; font-size:0.55rem; letter-spacing:0.5px;">
                                <th style="text-align:left; padding:4px 6px; border-bottom:1px solid #30363d;">Time</th>
                                <th style="text-align:left; padding:4px 6px; border-bottom:1px solid #30363d;">File</th>
                                <th style="text-align:right; padding:4px 6px; border-bottom:1px solid #30363d;">Lang</th>
                                <th style="text-align:right; padding:4px 6px; border-bottom:1px solid #30363d;">Orig</th>
                                <th style="text-align:right; padding:4px 6px; border-bottom:1px solid #30363d;">Skel</th>
                                <th style="text-align:right; padding:4px 6px; border-bottom:1px solid #30363d;">Save%</th>
                            </tr>
                        </thead>
                        <tbody>${rows}</tbody>
                    </table>
                `;
            }
        }
    }

    private static showOffline(): void {
        TokenSlayerTab.setText('ts-stat-files', '—');
        TokenSlayerTab.setText('ts-stat-saved', '—');
        TokenSlayerTab.setText('ts-stat-pct', '—');
        TokenSlayerTab.setText('ts-stat-cost', '—');
        const langTable = document.getElementById('ts-lang-table');
        if (langTable) {
            langTable.innerHTML = '<div style="color:#ff007f; text-align:center; padding:20px;">Dashboard offline — start TokenSlayer on port 8104</div>';
        }
    }

    private static setText(id: string, text: string): void {
        const el = document.getElementById(id);
        if (el) el.textContent = text;
    }

    private static setMsg(msg: string, color: string): void {
        const el = document.getElementById('ts-msg');
        if (el) {
            el.textContent = msg;
            el.style.color = color;
        }
    }

    private static escapeHtml(text: string): string {
        const div = document.createElement('div');
        div.textContent = text;
        return div.innerHTML;
    }
}

